import React, { useEffect, useRef, useState } from "react";
import Uppy from "@uppy/core";
import Dashboard from "@uppy/dashboard";
import Tus from "@uppy/tus";
import "@uppy/core/dist/style.min.css";
import "@uppy/dashboard/dist/style.min.css";
import { importUploadedFile } from "../../apiService";
import { getDjangoConstants } from "../../constants";
import { Callout, Intent } from "@blueprintjs/core";
import { useAppContext } from "../../AppContext";

const getUploadedFilename = (file, response, uploadedFilenameMap) => {
  const uploadUrl = response?.uploadURL;
  if (uploadUrl && uploadedFilenameMap.has(uploadUrl)) {
    return uploadedFilenameMap.get(uploadUrl);
  }

  const responseHeader = response?.xhr?.getResponseHeader?.("Upload-Filename");
  if (responseHeader) {
    return responseHeader;
  }

  return file.name;
};

const ResumableUploader = ({ datasetId, datasetType, group, groupId }) => {
  const dashboardRef = useRef(null);
  const uppyRef = useRef(null);
  const uploadedFilenameMapRef = useRef(new Map());
  const [isReady, setIsReady] = useState(false);
  const { ui, user } = getDjangoConstants();
  const allowedFileTypes = ui.uploader_allowed_file_extensions;
  
  const { state, toaster } = useAppContext();
  const chunkSizeMb = state.config?.UPLOADER?.chunk_size !== undefined
    ? parseInt(state.config.UPLOADER.chunk_size)
    : 100;
  const chunkSize = chunkSizeMb * 1024 * 1024;

  useEffect(() => {
    // Create Uppy instance
    const uppyInstance = new Uppy({
      id: "uppy-uploader",
      debug: true,
      autoProceed: false,
      restrictions: {
        maxNumberOfFiles: null,
        minNumberOfFiles: 1,
        allowedFileTypes,
      },
    }).use(Tus, {
      endpoint: "/omero_biomero/upload/",
      chunkSize,
      retryDelays: [0, 1000, 3000, 5000],
      limit: 5, // Allow up to 5 concurrent file uploads
      onAfterResponse: (req, res) => {
        const uploadUrl = req.getURL?.();
        const uploadedFilename = res.getHeader?.("Upload-Filename");
        if (uploadUrl && uploadedFilename) {
          uploadedFilenameMapRef.current.set(uploadUrl, uploadedFilename);
        }
      },
    });

    uppyRef.current = uppyInstance;
    setIsReady(true);

    return () => {
      uppyInstance.close();
    };
  }, [allowedFileTypes, chunkSize]);

  useEffect(() => {
    if (!uppyRef.current) return;

    uppyRef.current.setMeta({
      groupId: groupId != null ? String(groupId) : "",
      username: user.username || "",
    });
  }, [groupId, user.username]);

  useEffect(() => {
    if (!isReady || !dashboardRef.current || !uppyRef.current) return;

    // Mount Dashboard plugin
    uppyRef.current.use(Dashboard, {
      inline: true,
      target: dashboardRef.current,
      width: "100%",
      height: 500,
      showProgressDetails: true,
      proudlyDisplayPoweredByUppy: false,
      note: "Drag and drop supported files here or click to browse.",
    });

    // Handle upload success
    const onUploadSuccess = async (file, response) => {
      if (!datasetId) {
        console.warn("No dataset selected, skipping import trigger");
        return;
      }

      const uploadedFilename = getUploadedFilename(
        file,
        response,
        uploadedFilenameMapRef.current,
      );

      try {
        const responseData = await importUploadedFile(
          uploadedFilename,
          datasetId,
          datasetType,
          group,
          groupId,
        );
        const msg = responseData?.message || `Successfully queued ${uploadedFilename} for import`;
        toaster?.show({
          intent: "success",
          icon: "tick-circle",
          message: msg,
          timeout: 0,
        });
        if (response?.uploadURL) {
          uploadedFilenameMapRef.current.delete(response.uploadURL);
        }
      } catch (error) {
        console.error("Import trigger failed", error);
        toaster?.show({
          intent: "danger",
          icon: "error",
          message: `Import failed for ${uploadedFilename}: ${error.message}`,
          timeout: 0,
        });
        if (response?.uploadURL) {
          uploadedFilenameMapRef.current.delete(response.uploadURL);
        }
      }
    };

    uppyRef.current.on("upload-success", onUploadSuccess);

    // Surface upload-time failures (e.g. permission-denied finalizing the
    // upload server-side) directly instead of leaving the user to only see
    // Uppy's dashboard error state, or a confusing later "file not found"
    // when the import trigger inevitably can't find a file that was never
    // actually written to disk.
    const onUploadError = (file, error) => {
      console.error("Upload failed", file?.name, error);
      const serverMessage = error?.request?.responseText || error?.message || "Unknown error";
      toaster?.show({
        intent: "danger",
        icon: "error",
        message: `Upload failed for ${file?.name || "file"}: ${serverMessage}`,
        timeout: 0,
      });
    };
    uppyRef.current.on("upload-error", onUploadError);

    return () => {
      if (uppyRef.current) {
        uppyRef.current.off("upload-success", onUploadSuccess);
        uppyRef.current.off("upload-error", onUploadError);
        // Remove Dashboard plugin on cleanup
        const dashboardPlugin = uppyRef.current.getPlugin("Dashboard");
        if (dashboardPlugin) {
          uppyRef.current.removePlugin(dashboardPlugin);
        }
      }
    };
  }, [isReady, datasetId, datasetType, group, groupId]);

  if (!datasetId) {
    return (
      <Callout intent={Intent.WARNING}>
        Please select a dataset to upload to.
      </Callout>
    );
  }

  if (datasetType !== "Dataset") {
    return (
      <Callout intent={Intent.WARNING}>
        Web uploads are only supported for Datasets. Please select a Dataset.
      </Callout>
    );
  }

  return (
    <div className="resumable-uploader p-4">
      <div ref={dashboardRef} style={{ minHeight: "500px" }} />
    </div>
  );
};

export default ResumableUploader;
